import { NativeStackScreenProps } from '@react-navigation/native-stack';
import React, { useMemo, useRef, useState } from 'react';
import {
    Animated,
    Dimensions,
    FlatList,
    Image,
    Platform,
    ScrollView,
    StatusBar,
    TouchableOpacity,
    View
} from 'react-native';
import Calendar_My from '../../components/Calendar_My';
import { RootStackParamList } from '../../navigation/types';
import { styles } from './index.styles';

type Props = NativeStackScreenProps<RootStackParamList, 'HotelDetail'>;

const { width } = Dimensions.get('window');
const HEADER_HEIGHT = Platform.OS === 'ios' ? 90 : 70; // 包括状态栏高度

const HotelDetailScreen = ({ route, navigation }: Props) => {
    const { hotelId, hotelName } = route.params;
    const [currentImageIndex, setCurrentImageIndex] = useState(0);

    // 动画值：滚动偏移量
    const scrollY = useRef(new Animated.Value(0)).current;

    // 日历相关状态（保持不变）
    const [calendarVisible, setCalendarVisible] = useState(false);
    const [dateInfo, setDateInfo] = useState(() => {
        const today = new Date();
        const tomorrow = new Date(today);
        tomorrow.setDate(tomorrow.getDate() + 1);

        const formatDisplay = (date: Date) => `${date.getMonth() + 1}月${date.getDate()}日`;
        const formatStr = (date: Date) => {
            const year = date.getFullYear();
            const month = (date.getMonth() + 1).toString().padStart(2, '0');
            const day = date.getDate().toString().padStart(2, '0');
            return `${year}-${month}-${day}`;
        };

        return {
            startDisplay: formatDisplay(today),
            startStr: formatStr(today),
            endDisplay: formatDisplay(tomorrow),
            endStr: formatStr(tomorrow),
            nights: 1,
        };
    });

    // 模拟酒店图片数据（保持不变）
    const hotelImages = [
        'https://images.unsplash.com/photo-1591088398332-8a7791972843?auto=format&fit=crop&w=800&q=80',
        'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=800&q=80',
        'https://images.unsplash.com/photo-1595576508898-0ad5c879a061?auto=format&fit=crop&w=800&q=80',
    ];

    // 模拟房型数据（保持不变）
    const roomTypes = [
        {
            id: '1',
            name: '经典双床房',
            price: 198,
            specs: '2张1.2米单人床 40㎡',
            img: 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=800&q=80'
        },
        // ... 其余数据
    ];

    const sortedRooms = useMemo(() => [...roomTypes].sort((a, b) => a.price - b.price), []);

    // 动画插值
    // 背景颜色：滚动0-200从透明到白色
    const headerBackgroundColor = scrollY.interpolate({
        inputRange: [0, 200],
        outputRange: ['rgba(255,255,255,0)', 'rgba(255,255,255,1)'],
        extrapolate: 'clamp',
    });

    // 标题透明度：滚动0-100从0到1（初始完全透明）
    const titleOpacity = scrollY.interpolate({
        inputRange: [0, 100],
        outputRange: [0, 1],
        extrapolate: 'clamp',
    });

    // 返回箭头颜色：从白色渐变到深色
    const backIconColor = scrollY.interpolate({
        inputRange: [0, 200],
        outputRange: ['#fff', '#333'],
        extrapolate: 'clamp',
    });

    // 标题颜色：也可随背景变化，但这里保持黑色
    const titleColor = scrollY.interpolate({
        inputRange: [0, 200],
        outputRange: ['#333', '#333'], // 始终黑色，因为透明时不可见
        extrapolate: 'clamp',
    });

    // 渲染轮播图（保持不变）
    const renderBannerItem = ({ item }: { item: string }) => (
        <Image source={{ uri: item }} style={styles.bannerImage} />
    );

    const onScroll = Animated.event(
        [{ nativeEvent: { contentOffset: { y: scrollY } } }],
        { useNativeDriver: false }
    );

    const onBannerScroll = (event: any) => {
        const offsetX = event.nativeEvent.contentOffset.x;
        const index = Math.round(offsetX / width);
        if (index >= 0 && index < hotelImages.length && index !== currentImageIndex) {
            setCurrentImageIndex(index);
        }
    };

    return (
        <View style={styles.container}>
            <StatusBar barStyle="light-content" translucent backgroundColor="transparent" />

            {/* 顶部导航 - 使用绝对定位固定 */}
            <Animated.View style={[
                styles.header,
                { backgroundColor: headerBackgroundColor }
            ]}>
                <View style={styles.headerLeft}>
                    <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
                        <Animated.Text style={[styles.backIcon, { color: backIconColor }]}>
                            {'<'}
                        </Animated.Text>
                    </TouchableOpacity>
                </View>
                <Animated.Text
                    style={[
                        styles.headerTitle,
                        {
                            opacity: titleOpacity,
                            color: titleColor,
                        }
                    ]}
                    numberOfLines={1}
                >
                    {hotelName}
                </Animated.Text>
                <View style={styles.headerRight} />
            </Animated.View>

            <ScrollView
                bounces={false}
                showsVerticalScrollIndicator={false}
                onScroll={onScroll}
                scrollEventThrottle={16}
                contentContainerStyle={{ paddingTop: HEADER_HEIGHT }}
            >
                {/* 大图 Banner */}
                <View style={styles.bannerContainer}>
                    <FlatList
                        data={hotelImages}
                        renderItem={renderBannerItem}
                        keyExtractor={(_, index) => index.toString()}
                        horizontal
                        pagingEnabled
                        showsHorizontalScrollIndicator={false}
                        onScroll={onBannerScroll}
                        scrollEventThrottle={16}
                    />
                    <View style={styles.indicatorContainer}>
                        {hotelImages.map((_, index) => (
                            <View
                                key={index}
                                style={[
                                    styles.indicator,
                                    index === currentImageIndex && styles.indicatorActive
                                ]}
                            />
                        ))}
                    </View>
                </View>

                {/* 其余内容保持不变... */}
                {/* 请保留您原有的所有卡片、日历、房型列表代码，此处省略以节省篇幅 */}
            </ScrollView>

            {/* 日历组件保持不变 */}
            <Calendar_My
                visible={calendarVisible}
                onClose={() => setCalendarVisible(false)}
                onConfirm={(data) => {
                    setDateInfo({
                        startDisplay: data.startDisplay,
                        startStr: data.startStr,
                        endDisplay: data.endDisplay,
                        endStr: data.endStr,
                        nights: data.nights,
                    });
                    setCalendarVisible(false);
                }}
            />
        </View>
    );
};

export default HotelDetailScreen;
